// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address recipient, uint256 amt) public {
        amt = bound(amt, 1 wei, 1 ether);

        Receive r;
        if (recipient.code.length == 0) {
            r = new Receive();
            recipient = address(r);
        } else {
            r = new Receive();
        }

        vm.deal(address(this), amt);
        (bool ok,) = address(c).call{value: amt}("");
        require(ok);

        uint256 beforeRecipientBal = address(recipient).balance;
        uint256 beforeContractBal = address(c).balance;

        vm.prank(address(this));
        c.withdrawAll(recipient);

        uint256 afterRecipientBal = address(recipient).balance;
        uint256 afterContractBal = address(c).balance;

        assertTrue(afterContractBal == 0 && afterRecipientBal == beforeRecipientBal + beforeContractBal);
    }
}

contract Receive {
    receive() external payable {}
}
